287	     */
288	    default OwnerDto.AgeBandEnum ageBand(Owner owner) {
289	        if (owner == null || owner.getBirthDate() == null) {
290	            return null;
291	        }
292	        LocalDate reference = owner.getRegistrationDate();
293	        if (reference == null) {
294	            reference = LocalDate.now();
295	        }
296	        int age = Period.between(owner.getBirthDate(), reference).getYears();
297	        if (age < 18) {
298	            return OwnerDto.AgeBandEnum.MINOR;
299	        }
300	        if (age < 65) {
301	            return OwnerDto.AgeBandEnum.ADULT;
302	        }
303	        return OwnerDto.AgeBandEnum.SENIOR;
304	    }
