312	        if (owner == null || owner.getId() == null) {
313	            return null;
314	        }
315	        return "/api/owners/" + owner.getId();
316	    }
317	
318	    /**
319	     * Derives the owner's {@code ownerSegment}, formatted {@code '<TIER>_<AREA>'}. TIER is
